const laneTxs = (l: Lane): Result<readonly EntityTx[], RuntimeError> =>
  l.txs === undefined || l.txs.length === 0
    ? ok(l.txs ?? [])
    : mapErr(prioritizeWake(dedupAccountInputs(mergeJEvents(l.txs))), () => SCHEDULED_WAKE_CONFLICT);
